3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.rest.escalation.InvalidPostcodeException;
6	
7	/**
8	 * Validates an owner's postcode WHEN PRESENT, against the fixed per-region range derived from
9	 * the owner's city (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099). A city with no known region
10	 * accepts any 4-digit postcode. When absent the postcode is optional, so the step is a no-op
11	 * and the owner is still accepted — the request contract stays backward-compatible.
12	 *
13	 * <p>The 4-digit syntactic format is also enforced by the {@code postcode} bean-validation pattern
14	 * on the request DTO (so a malformed value is normally a 400 before this step); this step
15	 * re-checks the format so a malformed postcode is rejected even for a city with no known region,
16	 * then enforces the semantic region range. It runs on the built {@link Owner} before it is saved.
17	 */
18	public class CheckOwnerPostcode {
19	
20	    /** A valid postcode is exactly 4 digits. */
21	    private static final java.util.regex.Pattern FOUR_DIGITS = java.util.regex.Pattern.compile("\\d{4}");
22	
23	    public void service(@Val Owner owner) throws InvalidPostcodeException {
24	        String postcode = owner.getPostcode();
25	        if (postcode == null || postcode.isBlank()) {
26	            return; // optional when absent
27	        }
28	        String region = Locality.of(owner.getCity());
29	        if (!FOUR_DIGITS.matcher(postcode).matches()) {
30	            throw new InvalidPostcodeException(postcode, owner.getCity(), region);
31	        }
32	        int[] range = Locality.postcodeRange(region);
33	        if (range == null) {
34	            return; // city with no known region accepts any 4-digit postcode
35	        }
36	        int value = Integer.parseInt(postcode);
37	        if (value < range[0] || value > range[1]) {
38	            throw new InvalidPostcodeException(postcode, owner.getCity(), region);
39	        }
40	    }
41	}
