1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	
7	/**
8	 * Settles the household id for a new owner. The {@link Household#id(Owner) householdId} is now
9	 * DETERMINISTIC — the first 12 hex characters of SHA-256 over the normalized last name and
10	 * postcode — so it is always stamped on the owner regardless of {@code sharesHousehold}: owners
11	 * that share a last name and postcode automatically carry the identical value. The household's
12	 * size (this owner plus every existing member sharing the same householdId) is recorded on the
13	 * owner. Runs after {@link BuildOwner}.
14	 *
15	 * <p>This step no longer rejects duplicates and no longer needs {@code sharesHousehold} to form the
16	 * link: the link is implied by the shared householdId. Rejecting a household duplicate is
17	 * {@link CheckOwnerIdentityUnique}, which now keys off this householdId; {@code sharesHousehold}
18	 * only bypasses that rejection.
19	 */
20	public class AssignOwnerHousehold {
21	
22	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
23	        String householdId = Household.id(owner);
24	        owner.setHouseholdId(householdId);
25	        int householdSize = 1; // this owner
26	        for (Owner existing : ownerRepository.findAll()) {
27	            if (existing.getId() != null && existing.getId().equals(owner.getId())) {
28	                continue; // same record (e.g. re-save)
29	            }
30	            if (householdId.equals(Household.id(existing))) {
31	                householdSize++;
32	            }
33	        }
34	        owner.setHouseholdSize(householdSize);
35	    }
36	}
